// Report branding: a logo, a name and two colours, app-wide (App settings, data/config.json "reportBranding") or per
// project (overrides the app-wide values it sets). White-label hides "Generated by SEO Auditor" and shows the agency
// name instead. Everything is validated (logo: a PNG/JPEG/WebP/GIF data URI up to ~300 KB, colours #rrggbb) and
// escaped in the report, whose page CSP already allows only inline styles and data: images.
import { get } from "./db.mjs";
import { config } from "./gsc.mjs";
import { saveConfig } from "./dataforseo.mjs";

export const DEFAULT_BRANDING = { name: "", logo: "", primary: "", accent: "", whiteLabel: false };
const LOGO = /^data:image\/(png|jpeg|webp|gif);base64,[A-Za-z0-9+/]+={0,2}$/;
const COLOUR = /^#[0-9a-f]{6}$/i;
const MAX_LOGO = 400_000; // characters of base64 ≈ 300 KB image
const fail = (status, message) => { throw Object.assign(new Error(message), { status }); };
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

/** Keeps only valid fields; "" clears a field. Throws 400 on a bad logo or colour. */
export function cleanBranding(b = {}) {
  const out = {};
  if (b.name !== undefined) out.name = String(b.name).replace(/[\r\n]+/g, " ").trim().slice(0, 80);
  if (b.logo !== undefined) {
    const l = String(b.logo);
    if (l && (!LOGO.test(l) || l.length > MAX_LOGO)) fail(400, "Logo: a PNG, JPEG, WebP or GIF image up to about 300 KB");
    out.logo = l;
  }
  for (const k of ["primary", "accent"]) if (b[k] !== undefined) { const c = String(b[k]).trim(); if (c && !COLOUR.test(c)) fail(400, "Colours: #rrggbb, e.g. #1a5fb4"); out[k] = c.toLowerCase(); }
  if (b.whiteLabel !== undefined) out.whiteLabel = b.whiteLabel === "" || b.whiteLabel === null ? "" : Boolean(b.whiteLabel); // "" = as app-wide (projects)
  return out;
}

export const appBranding = () => ({ ...DEFAULT_BRANDING, ...(config().reportBranding || {}) });
export function saveAppBranding(b) { saveConfig({ reportBranding: { ...appBranding(), ...cleanBranding(b) } }); return appBranding(); }

/** Project branding (only the fields it sets), stored with the project's monitoring settings. */
export function projectBranding(projectId) {
  try { return JSON.parse(get("SELECT data FROM monitor_settings WHERE project_id=?", projectId)?.data || "{}").branding || {}; } catch { return {}; }
}
/** What a project's report uses: app-wide values, then the project's non-empty ones on top. */
export function brandingFor(projectId) {
  const out = appBranding(), own = projectBranding(projectId);
  for (const [k, v] of Object.entries(own)) if (v !== "" && v !== undefined && v !== null) out[k] = v;
  return out;
}

/** CSS, header and footer for the HTML report. defaultFooter is the unbranded footer text (already escaped HTML). */
export function brandingParts(b, defaultFooter) {
  const css = [b.primary && `h1{color:${b.primary}}.brandbar{border-bottom:3px solid ${b.primary}}`, b.accent && `h2{border-top-color:${b.accent}}.score{border-color:${b.accent}}`,
    ".brandbar{display:flex;align-items:center;gap:14px;padding-bottom:10px;margin-bottom:14px}.brandbar img{max-height:48px;max-width:220px}.brandbar b{font-size:16px}"].filter(Boolean).join("");
  const header = b.logo || b.name ? `<div class="brandbar">${b.logo ? `<img src="${esc(b.logo)}" alt="${esc(b.name || "Logo")}">` : ""}${b.name ? `<b>${esc(b.name)}</b>` : ""}</div>` : "";
  const footer = b.whiteLabel ? `Prepared${b.name ? ` by ${esc(b.name)}` : ""} on ${esc(new Date().toLocaleString("en-AU"))}. Lab and third-party figures are estimates; Search Console figures are Google's own data.` : defaultFooter;
  return { css, header, footer };
}
